fleet_event = {
	id = cara.1000
	hide_window = yes
	is_triggered_only = yes

	immediate = {
		# Reset any missed flags
		if = {
			limit = {
				any_system = {
					any_system_planet = { has_carrier_flag = fleet1_capital_destination }
				}
			}
			every_galaxy_planet = {
				limit = { has_carrier_flag = fleet1_capital_destination }
				remove_carrier_flag = fleet1_capital_destination
			}
		}

		# Roughly determine number of empires
		# Decide number of capitals to visit
		if = { # >=30 countries exist
			limit = {
				owner = {
					count_playable_country = {
						count > 29
					}
				}
			}
			log = "fleet 1 >=30 countries found, tag 10"
			# flag 10 capitals to visit
			while = {
				count = 10
				random_playable_country = {
					limit = {
						is_homicidal = no
						capital_scope = {
							NOT = { has_carrier_flag = fleet1_capital_destination }
						}
					}
					capital_scope = {
						set_carrier_flag = fleet1_capital_destination
						log = "1 fleet1_capital_destination set"
					}
				}
			}
		}
		else_if = { # >=15 countries exist
			limit = {
				owner = {
					count_playable_country = {
						count > 14
					}
				}
			}
			log = "fleet 1 >=15 countries found, tag 5"
			# flag 10 capitals to visit
			while = {
				count = 5
				random_playable_country = {
					limit = {
						is_homicidal = no
						capital_scope = {
							NOT = { has_carrier_flag = fleet1_capital_destination }
						}
					}
					capital_scope = {
						set_carrier_flag = fleet1_capital_destination
						log = "1 fleet1_capital_destination set"
					}
				}
			}
		}
		else_if = { # >12 countries exist
			limit = {
				owner = {
					count_playable_country = {
						count > 11
					}
				}
			}
			# flag 4 capitals to visit
			log = "fleet 1 >=12 countries found, tag 4"
			while = {
				count = 4
				random_playable_country = {
					limit = {
						is_homicidal = no
						capital_scope = {
							NOT = { has_carrier_flag = fleet1_capital_destination }
						}
					}
					capital_scope = {
						set_carrier_flag = fleet1_capital_destination
						log = "1 fleet1_capital_destination set"
					}
				}
			}
		}
		else_if = { # >=9 countries exist
			limit = {
				owner = {
					count_playable_country = {
						count > 8
					}
				}
			}
			# flag 3 capitals to visit
			log = "fleet 1 >=9 countries found, tag 3"
			while = {
				count = 6
				random_playable_country = {
					limit = {
						is_homicidal = no
						capital_scope = {
							NOT = { has_carrier_flag = fleet1_capital_destination }
						}
					}
					capital_scope = {
						set_carrier_flag = fleet1_capital_destination
						log = "1 fleet1_capital_destination set"
					}
				}
			}
		}
		else_if = { # >=6 countries exist
			limit = {
				owner = {
					count_playable_country = {
						count > 5
					}
				}
			}
			# flag 2 capitals to visit
			log = "fleet 1 >=6 countries found, tag 2"
			while = {
				count = 2
				random_playable_country = {
					limit = {
						is_homicidal = no
						capital_scope = {
							NOT = { has_carrier_flag = fleet1_capital_destination }
						}
					}
					capital_scope = {
						set_carrier_flag = fleet1_capital_destination
						log = "1 fleet1_capital_destination set"
					}
				}
			}
		}
		else = {
			# flag 1 capital to visit
			log = "fleet 1 <3 countries found, tag 1"
			random_playable_country = {
				limit = {
					is_homicidal = no
					capital_scope = {
						NOT = { has_carrier_flag = fleet1_capital_destination }
					}
				}
				capital_scope = {
					set_carrier_flag = fleet1_capital_destination
					log = "1 fleet1_capital_destination set"
				}
			}
		}

		solar_system = {
			closest_system = {
				use_bypasses = yes
				limit = {
					is_capital_system = yes
					any_system_planet = { has_carrier_flag = fleet1_capital_destination }
				}
				random_system_planet = {
					limit = { has_carrier_flag = fleet1_capital_destination }
					save_event_target_as = fleet1_next_capital_destination
				}
				root = {
					auto_move_to_planet = {
						target = event_target:fleet1_next_capital_destination
						clear_auto_move_on_arrival = no
						arrival_effect = fleet1_continue_journey
					}
				}
			}
		}
	}
}

