fleet_event = {
	id = cara.3000
	hide_window = yes
	is_triggered_only = yes

	immediate = {
		# Reset any missed flags
		if = {
			limit = {
				any_system = {
					any_system_planet = { has_carrier_flag = fleet3_capital_destination }
				}
			}
			every_galaxy_planet = {
				limit = { has_carrier_flag = fleet3_capital_destination }
				remove_carrier_flag = fleet3_capital_destination
			}
		}

		# Roughly determine number of empires
		# Decide number of capitals to visit
		if = { # >=30 countries exist
			limit = {
				owner = {
					count_playable_country = {
						count > 29
					}
				}
			}
			log = "fleet 3 >=30 countries found, tag 10"
			# flag 10 capitals to visit
			while = {
				count = 10
				random_playable_country = {
					limit = {
						is_homicidal = no
						capital_scope = {
							NOT = { has_carrier_flag = fleet3_capital_destination }
						}
					}
					capital_scope = {
						set_carrier_flag = fleet3_capital_destination
						log = "1 fleet3_capital_destination set"
					}
				}
			}
		}
